function parseDate(v){
  if(v===undefined||v===null||v==='') return null;
  const s=String(v).trim();
  let m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/);
  if(m){ const d=DateTime.fromObject({day:+m[1],month:+m[2],year:+m[3]},{zone:'Europe/Istanbul'}); return d.isValid?d.startOf('day'):null; }
  m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m){ const d=DateTime.fromObject({year:+m[1],month:+m[2],day:+m[3]},{zone:'Europe/Istanbul'}); return d.isValid?d.startOf('day'):null; }
  const d=DateTime.fromISO(s,{zone:'Europe/Istanbul'});
  return d.isValid?d.startOf('day'):null;
}
function num(v){
  if(v===undefined||v===null||v==='') return 0;
  let s=String(v).replace(/[^\d.,-]/g,'');
  if(s.indexOf(',')>-1 && s.indexOf('.')>-1){ s=s.replace(/\./g,'').replace(',', '.'); }
  else if(s.indexOf(',')>-1){ s=s.replace(',', '.'); }
  const n=parseFloat(s); return isNaN(n)?0:n;
}
function fmt(n){ return Number(n).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}); }

const rows=$input.all().map(i=>i.json);
const now=$now.setZone('Europe/Istanbul');
const today=now.startOf('day');
const target=now.minus({months:1});
const prev=now.minus({months:2});
const mkey=(dt)=>dt.toFormat('yyyy-MM');
const tKey=mkey(target), pKey=mkey(prev);

const ciro={}, tahsilat={}, musteriCiro={};
let acikToplam=0, gecikmisToplam=0, gecikmisAdet=0;

for(const r of rows){
  const tutar=num(r.tutar);
  const fd=parseDate(r.fatura_tarihi);
  const od=parseDate(r.odeme_tarihi);
  const durum=String(r.durum||'').trim().toLocaleLowerCase('tr-TR');
  const paid=(durum==='ödendi'||durum==='odendi');

  if(fd){ const k=mkey(fd); ciro[k]=(ciro[k]||0)+tutar; if(k===tKey){ const m=r.musteri||'—'; musteriCiro[m]=(musteriCiro[m]||0)+tutar; } }
  if(od && paid){ const k=mkey(od); tahsilat[k]=(tahsilat[k]||0)+tutar; }

  const acik=!(paid||durum==='iptal'||durum==='kapandı'||durum==='kapandi');
  if(acik){ acikToplam+=tutar; const vd=parseDate(r.vade_tarihi); if(vd && vd<today){ gecikmisToplam+=tutar; gecikmisAdet++; } }
}

const ciroT=ciro[tKey]||0, ciroP=ciro[pKey]||0;
const tahsilatT=tahsilat[tKey]||0;
const buyume = ciroP>0 ? ((ciroT-ciroP)/ciroP*100) : null;
const tahsilatOrani = ciroT>0 ? (tahsilatT/ciroT*100) : null;

const trend=[];
for(let i=5;i>=0;i--){ const d=now.minus({months:i+1}); const k=mkey(d); trend.push({ay:d.toFormat('MM.yyyy'), ciro:ciro[k]||0}); }

const topArr=Object.entries(musteriCiro).sort((a,b)=>b[1]-a[1]).slice(0,5);
const topM=topArr.map(([m,v])=>`   • ${m}: ${fmt(v)} TL`).join('\n')||'   —';
const trendTxt=trend.map(t=>`   ${t.ay}: ${fmt(t.ciro)} TL`).join('\n');
const ayAdi=target.setLocale('tr').toFormat('LLLL yyyy');

const kpi=
`MirFix Aylık Ölçekleme Raporu — ${ayAdi}\n`+
`==========================================\n\n`+
`📈 Aylık ciro (satış): ${fmt(ciroT)} TL\n`+
`↔️  Önceki ay: ${fmt(ciroP)} TL  →  Büyüme: ${buyume===null?'—':(buyume>=0?'+':'')+buyume.toFixed(1)+'%'}\n`+
`💵 Bu ay tahsil edilen: ${fmt(tahsilatT)} TL  (tahsilat oranı: ${tahsilatOrani===null?'—':tahsilatOrani.toFixed(0)+'%'})\n`+
`📂 Toplam açık alacak: ${fmt(acikToplam)} TL\n`+
`🔴 Gecikmiş alacak: ${fmt(gecikmisToplam)} TL (${gecikmisAdet} fatura)\n\n`+
`Son 6 ay ciro trendi:\n${trendTxt}\n\n`+
`En büyük 5 müşteri (${ayAdi}):\n${topM}`;

const rakamlar={ay:ayAdi, ciro:ciroT, onceki_ay_ciro:ciroP, buyume_yuzde:buyume,
  tahsilat:tahsilatT, tahsilat_orani:tahsilatOrani, acik_alacak:acikToplam,
  gecikmis_alacak:gecikmisToplam, gecikmis_adet:gecikmisAdet, trend,
  en_buyuk_musteriler:topArr.map(([m,v])=>({musteri:m,ciro:v}))};

return [{ json:{ kpi_metni:kpi, rakamlar } }];

